// Package calc evaluates 64-bit signed integer arithmetic expressions with
// exact overflow detection.
package calc

import (
	"bufio"
	"errors"
	"io"
	"math"
	"strconv"
)

// Errors reported by Eval.
var (
	ErrSyntax   = errors.New("syntax error")
	ErrDivZero  = errors.New("division by zero")
	ErrOverflow = errors.New("integer overflow")
)

// Eval evaluates a single expression according to the grammar
//
//	expr    := term    (('+' | '-') term)*
//	term    := unary   (('*' | '/' | '%') unary)*
//	unary   := '-' unary | primary
//	primary := NUMBER | '(' expr ')'
//
// Spaces and tabs may separate tokens.
func Eval(s []byte) (int64, error) {
	p := parser{src: s}
	v, err := p.expr()
	if err != nil {
		return 0, err
	}
	if p.peek() != 0 {
		return 0, ErrSyntax
	}
	return v, nil
}

type parser struct {
	src []byte
	pos int
}

// peek skips blanks and returns the next byte, or 0 at end of input.
func (p *parser) peek() byte {
	for p.pos < len(p.src) && (p.src[p.pos] == ' ' || p.src[p.pos] == '\t') {
		p.pos++
	}
	if p.pos == len(p.src) {
		return 0
	}
	return p.src[p.pos]
}

func (p *parser) expr() (int64, error) {
	acc, err := p.term()
	if err != nil {
		return 0, err
	}
	for {
		op := p.peek()
		if op != '+' && op != '-' {
			return acc, nil
		}
		p.pos++
		rhs, err := p.term()
		if err != nil {
			return 0, err
		}
		if op == '+' {
			acc, err = add(acc, rhs)
		} else {
			acc, err = sub(acc, rhs)
		}
		if err != nil {
			return 0, err
		}
	}
}

func (p *parser) term() (int64, error) {
	acc, err := p.unary()
	if err != nil {
		return 0, err
	}
	for {
		op := p.peek()
		if op != '*' && op != '/' && op != '%' {
			return acc, nil
		}
		p.pos++
		rhs, err := p.unary()
		if err != nil {
			return 0, err
		}
		switch op {
		case '*':
			acc, err = mul(acc, rhs)
		case '/':
			acc, err = div(acc, rhs)
		default:
			acc, err = rem(acc, rhs)
		}
		if err != nil {
			return 0, err
		}
	}
}

// unary handles chains of '-' iteratively so long chains cannot exhaust the stack.
func (p *parser) unary() (int64, error) {
	negations := 0
	for p.peek() == '-' {
		p.pos++
		negations++
	}
	v, err := p.primary()
	if err != nil {
		return 0, err
	}
	if negations == 0 {
		return v, nil
	}
	if v == math.MinInt64 {
		return 0, ErrOverflow
	}
	if negations%2 == 1 {
		v = -v
	}
	return v, nil
}

func (p *parser) primary() (int64, error) {
	switch c := p.peek(); {
	case c == '(':
		p.pos++
		v, err := p.expr()
		if err != nil {
			return 0, err
		}
		if p.peek() != ')' {
			return 0, ErrSyntax
		}
		p.pos++
		return v, nil
	case c >= '0' && c <= '9':
		return p.number()
	default:
		return 0, ErrSyntax
	}
}

func (p *parser) number() (int64, error) {
	var v int64
	overflow := false
	for p.pos < len(p.src) && p.src[p.pos] >= '0' && p.src[p.pos] <= '9' {
		d := int64(p.src[p.pos] - '0')
		if v > (math.MaxInt64-d)/10 {
			overflow = true
		} else {
			v = v*10 + d
		}
		p.pos++
	}
	if overflow {
		return 0, ErrOverflow
	}
	return v, nil
}

func add(a, b int64) (int64, error) {
	s := a + b
	if (a >= 0) == (b >= 0) && (s >= 0) != (a >= 0) {
		return 0, ErrOverflow
	}
	return s, nil
}

func sub(a, b int64) (int64, error) {
	d := a - b
	if (a >= 0) != (b >= 0) && (d >= 0) != (a >= 0) {
		return 0, ErrOverflow
	}
	return d, nil
}

func mul(a, b int64) (int64, error) {
	if a == 0 || b == 0 {
		return 0, nil
	}
	p := a * b
	if (a == -1 && b == math.MinInt64) || (b == -1 && a == math.MinInt64) || p/b != a {
		return 0, ErrOverflow
	}
	return p, nil
}

func div(a, b int64) (int64, error) {
	if b == 0 {
		return 0, ErrDivZero
	}
	if a == math.MinInt64 && b == -1 {
		return 0, ErrOverflow
	}
	return a / b, nil
}

func rem(a, b int64) (int64, error) {
	if b == 0 {
		return 0, ErrDivZero
	}
	if b == -1 {
		return 0, nil // also covers MinInt64 % -1
	}
	return a % b, nil
}

func isBlank(line []byte) bool {
	for _, c := range line {
		if c != ' ' && c != '\t' {
			return false
		}
	}
	return true
}

// Run evaluates each line of r and writes its value, or "error", to w.
// Blank lines (empty or only spaces/tabs) produce no output.
func Run(r io.Reader, w io.Writer) error {
	br := bufio.NewReaderSize(r, 1<<16)
	var out []byte
	for {
		line, err := br.ReadSlice('\n')
		if errors.Is(err, bufio.ErrBufferFull) {
			// Overlong line: accumulate it in full.
			full := append([]byte(nil), line...)
			for errors.Is(err, bufio.ErrBufferFull) {
				line, err = br.ReadSlice('\n')
				full = append(full, line...)
			}
			line = full
		}
		if err != nil && !errors.Is(err, io.EOF) {
			return err
		}
		if n := len(line); n > 0 && line[n-1] == '\n' {
			line = line[:n-1]
		}
		if !isBlank(line) {
			if v, evalErr := Eval(line); evalErr != nil {
				out = append(out, "error"...)
			} else {
				out = strconv.AppendInt(out, v, 10)
			}
			out = append(out, '\n')
			if len(out) >= 1<<15 {
				if _, werr := w.Write(out); werr != nil {
					return werr
				}
				out = out[:0]
			}
		}
		if err != nil { // io.EOF
			break
		}
	}
	_, err := w.Write(out)
	return err
}

package calc

import (
	"bytes"
	"strings"
	"testing"
)

func TestRun(t *testing.T) {
	in := strings.Join([]string{
		"1 + 2 * 3", "-7 / 2", "(1 + 2", "9223372036854775807 + 1",
		"", "  \t", "-7 % 3", "7 % -3", "1 / 0",
		"(-9223372036854775807 - 1) % -1", "(-9223372036854775807 - 1) / -1",
		"-(-9223372036854775807 - 1)", "9223372036854775808", "--5", "+1", "()", "1 2",
	}, "\n")
	want := "7\n-3\nerror\nerror\n-1\n1\nerror\n0\nerror\nerror\nerror\n5\nerror\nerror\nerror\n"
	var out bytes.Buffer
	if err := Run(strings.NewReader(in), &out); err != nil {
		t.Fatal(err)
	}
	if out.String() != want {
		t.Errorf("got:\n%s\nwant:\n%s", out.String(), want)
	}
}

// Package lru implements a fixed-capacity least-recently-used cache and a
// line-oriented command simulator on top of it.
package lru

import (
	"bufio"
	"bytes"
	"errors"
	"fmt"
	"io"
	"strconv"
)

const nilIdx = -1

type node struct {
	key, value string
	prev, next int32
}

// Cache is an LRU cache of string keys and values. All operations are O(1)
// expected time. Nodes live in a slice and are linked by index, which keeps
// the structure compact and avoids per-entry heap allocations.
type Cache struct {
	capacity   int
	index      map[string]int32
	nodes      []node
	free       []int32
	head, tail int32 // head is most recently used
}

// New returns an empty cache that holds at most capacity keys (capacity ≥ 1).
func New(capacity int) *Cache {
	return &Cache{
		capacity: capacity,
		index:    make(map[string]int32, min(capacity, 1<<16)),
		head:     nilIdx,
		tail:     nilIdx,
	}
}

// Len reports the number of keys held.
func (c *Cache) Len() int { return len(c.index) }

// Get returns the value for key and marks it most recently used.
func (c *Cache) Get(key []byte) (string, bool) {
	i, ok := c.index[string(key)]
	if !ok {
		return "", false
	}
	c.moveToFront(i)
	return c.nodes[i].value, true
}

// Set inserts or overwrites key, marks it most recently used and evicts the
// least recently used key if the capacity is exceeded.
func (c *Cache) Set(key, value []byte) {
	if i, ok := c.index[string(key)]; ok {
		if c.nodes[i].value != string(value) {
			c.nodes[i].value = string(value)
		}
		c.moveToFront(i)
		return
	}
	var i int32
	if n := len(c.free); n > 0 {
		i = c.free[n-1]
		c.free = c.free[:n-1]
	} else {
		i = int32(len(c.nodes))
		c.nodes = append(c.nodes, node{})
	}
	k := string(key)
	c.nodes[i] = node{key: k, value: string(value), prev: nilIdx, next: nilIdx}
	c.index[k] = i
	c.pushFront(i)
	if len(c.index) > c.capacity {
		c.remove(c.tail)
	}
}

// Del removes key and reports whether it was present.
func (c *Cache) Del(key []byte) bool {
	i, ok := c.index[string(key)]
	if ok {
		c.remove(i)
	}
	return ok
}

func (c *Cache) remove(i int32) {
	c.unlink(i)
	delete(c.index, c.nodes[i].key)
	c.nodes[i] = node{}
	c.free = append(c.free, i)
}

func (c *Cache) moveToFront(i int32) {
	if c.head == i {
		return
	}
	c.unlink(i)
	c.pushFront(i)
}

func (c *Cache) pushFront(i int32) {
	n := &c.nodes[i]
	n.prev, n.next = nilIdx, c.head
	if c.head != nilIdx {
		c.nodes[c.head].prev = i
	} else {
		c.tail = i
	}
	c.head = i
}

func (c *Cache) unlink(i int32) {
	n := &c.nodes[i]
	if n.prev != nilIdx {
		c.nodes[n.prev].next = n.next
	} else {
		c.head = n.next
	}
	if n.next != nilIdx {
		c.nodes[n.next].prev = n.prev
	} else {
		c.tail = n.prev
	}
	n.prev, n.next = nilIdx, nilIdx
}

// Run reads a capacity line followed by SET/GET/DEL/SIZE commands from r and
// writes each command's output to w. Unrecognised lines are ignored.
func Run(r io.Reader, w io.Writer) error {
	sc := bufio.NewScanner(r)
	sc.Buffer(make([]byte, 1<<16), 1<<20)

	if !sc.Scan() {
		return sc.Err()
	}
	capacity, err := strconv.Atoi(string(bytes.TrimSpace(sc.Bytes())))
	if err != nil || capacity < 1 {
		return fmt.Errorf("invalid capacity %q", sc.Bytes())
	}
	cache := New(capacity)

	var out []byte
	for sc.Scan() {
		line := bytes.TrimSuffix(sc.Bytes(), []byte{'\r'})
		cmd, rest, _ := bytes.Cut(line, []byte{' '})
		switch string(cmd) {
		case "SET":
			key, value, ok := bytes.Cut(rest, []byte{' '})
			if ok {
				cache.Set(key, value)
			}
			continue
		case "GET":
			if v, ok := cache.Get(rest); ok {
				out = append(out, v...)
			} else {
				out = append(out, "NULL"...)
			}
		case "DEL":
			if cache.Del(rest) {
				out = append(out, '1')
			} else {
				out = append(out, '0')
			}
		case "SIZE":
			out = strconv.AppendInt(out, int64(cache.Len()), 10)
		default:
			continue
		}
		out = append(out, '\n')
		if len(out) >= 1<<15 {
			if _, err := w.Write(out); err != nil {
				return err
			}
			out = out[:0]
		}
	}
	if err := sc.Err(); err != nil && !errors.Is(err, io.EOF) {
		return err
	}
	_, err = w.Write(out)
	return err
}

// Command app bundles three independent stdin/stdout tools: wordfreq, lru and calc.
package main

import (
	"bufio"
	"fmt"
	"io"
	"os"

	"suite/calc"
	"suite/lru"
	"suite/wordfreq"
)

type command func(r io.Reader, w io.Writer) error

var commands = map[string]command{
	"wordfreq": func(r io.Reader, w io.Writer) error { return wordfreq.Run(r, w, 10) },
	"lru":      lru.Run,
	"calc":     calc.Run,
}

func main() {
	if len(os.Args) < 2 {
		usage()
	}
	cmd, ok := commands[os.Args[1]]
	if !ok {
		usage()
	}
	out := bufio.NewWriterSize(os.Stdout, 1<<16)
	err := cmd(os.Stdin, out)
	if ferr := out.Flush(); err == nil {
		err = ferr
	}
	if err != nil {
		fmt.Fprintf(os.Stderr, "app %s: %v\n", os.Args[1], err)
		os.Exit(1)
	}
}

func usage() {
	fmt.Fprintln(os.Stderr, "usage: app wordfreq|lru|calc < input")
	os.Exit(2)
}

// Package wordfreq counts case-insensitive ASCII words and reports the most frequent ones.
package wordfreq

import (
	"cmp"
	"errors"
	"io"
	"slices"
	"strconv"
)

// lower maps ASCII letters to their lowercase form and every other byte to 0.
var lower = func() (t [256]byte) {
	for c := 'a'; c <= 'z'; c++ {
		t[c] = byte(c)
		t[c-'a'+'A'] = byte(c)
	}
	return t
}()

// Entry is a word together with its number of occurrences.
type Entry struct {
	Word  string
	Count int
}

// Count reads r to EOF and returns the occurrence count of every word.
// A word is a maximal run of ASCII letters, folded to lowercase.
func Count(r io.Reader) (map[string]int, error) {
	counts := make(map[string]*int)
	buf := make([]byte, 1<<20)
	var word []byte // current (possibly partial) lowercase word

	flush := func() {
		if len(word) == 0 {
			return
		}
		if p, ok := counts[string(word)]; ok {
			*p++
		} else {
			n := 1
			counts[string(word)] = &n
		}
		word = word[:0]
	}

	for {
		n, err := r.Read(buf)
		for _, c := range buf[:n] {
			if l := lower[c]; l != 0 {
				word = append(word, l)
			} else {
				flush()
			}
		}
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			return nil, err
		}
	}
	flush()

	result := make(map[string]int, len(counts))
	for w, p := range counts {
		result[w] = *p
	}
	return result, nil
}

// Top returns up to n entries ordered by count descending, then word ascending.
func Top(counts map[string]int, n int) []Entry {
	entries := make([]Entry, 0, len(counts))
	for w, c := range counts {
		entries = append(entries, Entry{w, c})
	}
	slices.SortFunc(entries, func(a, b Entry) int {
		if c := cmp.Compare(b.Count, a.Count); c != 0 {
			return c
		}
		return cmp.Compare(a.Word, b.Word)
	})
	return entries[:min(n, len(entries))]
}

// Run writes the n most frequent words of r to w, one "<count> <word>" per line.
func Run(r io.Reader, w io.Writer, n int) error {
	counts, err := Count(r)
	if err != nil {
		return err
	}
	var line []byte
	for _, e := range Top(counts, n) {
		line = strconv.AppendInt(line[:0], int64(e.Count), 10)
		line = append(line, ' ')
		line = append(line, e.Word...)
		line = append(line, '\n')
		if _, err := w.Write(line); err != nil {
			return err
		}
	}
	return nil
}

package wordfreq

import (
	"bytes"
	"strings"
	"testing"
)

func TestRun(t *testing.T) {
	tests := []struct{ in, want string }{
		{"The cat and the hat.", "2 the\n1 and\n1 cat\n1 hat\n"},
		{"don't stop_me 4now, now-NOW", "3 now\n1 don\n1 me\n1 stop\n1 t\n"},
		{"", ""},
		{"caf\xc3\xa9 CAF\xffe", "2 caf\n1 e\n"},
	}
	for _, tt := range tests {
		var out bytes.Buffer
		if err := Run(strings.NewReader(tt.in), &out, 10); err != nil {
			t.Fatal(err)
		}
		if out.String() != tt.want {
			t.Errorf("Run(%q) = %q, want %q", tt.in, out.String(), tt.want)
		}
	}
}
